import { useState } from 'react';
import {
  Screen,
  Card,
  Grid,
  Stack,
  Row,
  TextField,
  SelectField,
  Button,
  Alert,
  KeyBar,
} from '@nexti/ds';

type Errors = Partial<Record<'ORDEN' | 'EMPRESA' | 'VALOR', string>>;
type Status = { tone: 'info' | 'success' | 'warning' | 'error'; text: string } | null;

const onlyDigits = (v: string, max: number) => v.replace(/\D/g, '').slice(0, max);

// VALOR: formato 9(9)V99 -> hasta 9 enteros y 2 decimales
const sanitizeValor = (v: string) => {
  const clean = v.replace(',', '.').replace(/[^\d.]/g, '');
  const [intPart, ...rest] = clean.split('.');
  const ints = intPart.slice(0, 9);
  if (rest.length === 0) return ints;
  return `${ints}.${rest.join('').slice(0, 2)}`;
};

export default function PagoOrdenes({ navigate }: { navigate: (to: string) => void }) {
  const [orden, setOrden] = useState('');
  const [empresa, setEmpresa] = useState('');
  const [servic, setServic] = useState('');
  const [tipcta, setTipcta] = useState('');
  const [cuenta, setCuenta] = useState('');
  const [valor, setValor] = useState('');
  const [canal, setCanal] = useState('WEB');
  const [clave, setClave] = useState('');
  const [errors, setErrors] = useState<Errors>({});
  const [mensaje, setMensaje] = useState<Status>(null);
  const [enviado, setEnviado] = useState(false);

  // CLAVE es un campo oculto (atributo "dark"): se guarda el valor real y se muestra enmascarado
  const onClave = (v: string) => {
    if (v.length < clave.length) {
      setClave(clave.slice(0, v.length));
    } else {
      setClave((clave + v.slice(clave.length)).slice(0, 6));
    }
  };

  const pagar = () => {
    const e: Errors = {};
    if (!orden) e.ORDEN = 'El número de orden es obligatorio';
    if (!empresa) e.EMPRESA = 'La empresa es obligatoria';
    if (valor && Number.isNaN(Number(valor))) e.VALOR = 'Valor no válido';
    setErrors(e);
    if (Object.keys(e).length > 0) {
      setEnviado(false);
      setMensaje({ tone: 'error', text: 'Complete los campos obligatorios (*) antes de pagar.' });
      return;
    }
    setEnviado(true);
    setMensaje({
      tone: 'success',
      text: `Orden ${orden} enviada a pago. Continúe para ver el resultado.`,
    });
  };

  const cancelar = () => {
    setOrden('');
    setEmpresa('');
    setServic('');
    setTipcta('');
    setCuenta('');
    setValor('');
    setCanal('WEB');
    setClave('');
    setErrors({});
    setEnviado(false);
    setMensaje({ tone: 'info', text: 'Operación cancelada. Se limpiaron los datos del formulario.' });
  };

  const volver = () => navigate('SCR-PAGOMEN');

  return (
    <Screen
      title="Pago de órdenes"
      code="PAGOORD"
      keys={
        <KeyBar
          actions={[
            { key: 'ENTER', label: 'Pagar', onPress: pagar, primary: true },
            { key: 'PF3', label: 'Volver', onPress: volver },
            { key: 'PF12', label: 'Cancelar', onPress: cancelar },
          ]}
        />
      }
    >
      <Stack>
        <Card title="Datos de la orden">
          <Grid columns={2}>
            <div data-field="ORDEN">
              <TextField
                label="Número de orden"
                required
                numeric
                maxLength={7}
                hint="Hasta 7 dígitos"
                error={errors.ORDEN}
                value={orden}
                onChange={(v: string) => setOrden(onlyDigits(v, 7))}
              />
            </div>
            <div data-field="EMPRESA">
              <TextField
                label="Empresa"
                required
                numeric
                maxLength={5}
                hint="Hasta 5 dígitos"
                error={errors.EMPRESA}
                value={empresa}
                onChange={(v: string) => setEmpresa(onlyDigits(v, 5))}
              />
            </div>
            <div data-field="SERVIC">
              <TextField
                label="Servicio"
                maxLength={10}
                hint="Hasta 10 caracteres"
                value={servic}
                onChange={(v: string) => setServic(v.slice(0, 10))}
              />
            </div>
            <div data-field="TIPCTA">
              <TextField
                label="Tipo de cuenta"
                maxLength={3}
                hint="3 caracteres"
                value={tipcta}
                onChange={(v: string) => setTipcta(v.slice(0, 3).toUpperCase())}
              />
            </div>
            <div data-field="CUENTA">
              <TextField
                label="Cuenta"
                numeric
                maxLength={10}
                hint="Hasta 10 dígitos"
                value={cuenta}
                onChange={(v: string) => setCuenta(onlyDigits(v, 10))}
              />
            </div>
            <div data-field="VALOR">
              <TextField
                label="Valor"
                numeric
                maxLength={12}
                hint="Hasta 9 enteros y 2 decimales (ej. 1250.50)"
                error={errors.VALOR}
                value={valor}
                onChange={(v: string) => setValor(sanitizeValor(v))}
              />
            </div>
          </Grid>
        </Card>

        <Card title="Canal y aprobación">
          <Grid columns={2}>
            <div data-field="CANAL">
              <SelectField
                label="Canal (WEB/OFI)"
                hint="Por defecto: WEB"
                options={[
                  { value: 'WEB', label: 'WEB - Canal web' },
                  { value: 'OFI', label: 'OFI - Oficina' },
                ]}
                value={canal}
                onChange={(v: string) => setCanal(v)}
              />
            </div>
            <div data-field="CLAVE">
              <TextField
                label="Clave de aprobación"
                maxLength={6}
                hint="6 caracteres. El campo se muestra oculto."
                value={'•'.repeat(clave.length)}
                onChange={onClave}
              />
            </div>
          </Grid>
        </Card>

        <div data-field="MENSAJE" aria-live="polite">
          {mensaje ? (
            <Alert tone={mensaje.tone}>{mensaje.text}</Alert>
          ) : (
            <Alert tone="info">Sin mensajes. Los campos con * son obligatorios.</Alert>
          )}
        </div>

        <Row>
          <Button variant="primary" shortcut="ENTER" onClick={pagar}>
            Pagar
          </Button>
          <Button variant="secondary" shortcut="PF12" onClick={cancelar}>
            Cancelar
          </Button>
          <Button variant="ghost" shortcut="PF3" onClick={volver}>
            Volver
          </Button>
          {enviado && (
            <Button variant="primary" onClick={() => navigate('SCR-PAGORES')}>
              Ver resultado del pago
            </Button>
          )}
        </Row>
      </Stack>
    </Screen>
  );
}
